": 35.225249088, "longitude": 136.29067678, "history": "この男女二柱の大神は、はじめて夫婦の道をおこされ、わが国土と万有の神神と、その主宰神としての天照大神をお生みになられましたので昔から、わが日本国の祖神さまと仰がれ奈良時代の初めにできた「古事記」には、すでに淡海の多賀に鎮座という記事が見えています。そこで早くより朝野尊崇あつく、延命長寿の守護神を信仰されてきました数数の霊験は、社蔵の古文書やご宝物、また境内にのこる寿命石、太閤蔵、文部省指定の各勝「奥書院庭園」などが明らかに物語っておりますと伝えられています。伝承には諸説あります。", "deities": ["伊邪那岐大神", "伊邪那美大神"], "benefits": [], "lineages": [], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=5993", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "shiga-shrine-2", "municipality": "犬上郡多賀町"}, {"name": "伏見稲荷大社", "prefecture": "京都府", "address": "京都府京都市伏見区深草藪之内68", "latitude": 34.967150607, "longitude": 135.773200174, "history": "伏見稲荷大社は京都府に鎮座する神社であり、由緒については諸説があると伝えられています。", "deities": ["宇迦之御魂大神"], "benefits": [], "lineages": ["稲荷信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=8733", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "kyoto", "municipality": "京都市"}, {"name": "八坂神社", "prefecture": "京都府", "address": "京都府京都市東山区祇園町北側625", "latitude": 35.0036027, "longitude": 135.7782611, "history": "八坂神社は明治元年まで祇園社と称していたので、祇園さんの名で親しまれ信仰されている。社伝によると八坂神社は斉明天皇２年（６５６）高麗より来朝せる調進副使の伊利之使主（いりしおみ）が新羅国牛頭山（ごずさん）にます素戔嗚尊を山城国愛宕（おたぎ）郡八坂郷に祀り、八坂造の姓を賜わったのに始まると伝えられています。伝承には諸説あります。", "deities": ["素戔嗚尊"], "benefits": [], "lineages": ["祇園信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4499", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://www.openstreetmap.org/way/328903218", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "kyoto-shrine-1", "municipality": "京都市"}, {"name": "住吉大社", "prefecture": "大阪府", "address": "大阪府大阪市住吉区住吉2-9-89", "latitude": 34.612746657, "longitude": 135.493347743, "history": "底筒男命、中筒男命、表筒男命の三神を総称して住吉大神と申上げ、伊弉諾尊があはぎはらに祓除せられたとき、海の中より生れた神樣です。神功皇后は、新羅御出兵に当って、住吉大神の御加護を得ておおいに国威を輝かせられ、御凱旋の後、大神の御神託によって此の地に御鎮祭になりましたと伝えられています。伝承には諸説あります。", "deities": ["底筒男命", "中筒男命", "表筒男命", "息長足姫命"], "benefits": [], "lineages": ["住吉信仰"], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=4910", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "source_type": "other", "field_name": "coordinates", "notes": "住所・自治体と座標を照合し、地図上の位置確認に使用。"}], "official_url": null, "slug": "osaka", "municipality": "大阪市"}, {"name": "枚岡神社", "prefecture": "大阪府", "address": "大阪府東大阪市出雲井町7-16", "latitude": 34.669969175, "longitude": 135.650693159, "history": "枚岡神社は大阪府に鎮座する神社であり、由緒については諸説があると伝えられています。", "deities": ["天児屋根大神", "比売大神"], "benefits": [], "lineages": [], "sources": [{"name": "皇學館大学・県神社庁協力「新全国神社検索」", "url": "https://jinja-net.jp/jinja-all/jsearch3all.php?jinjya=38858", "source_type": "shrine_association", "field_name": "shrine_information", "notes": "神社名・所在地・由緒・御祭神の確認に使用。未確認の情報は記載していません。"}, {"name": "座標参照・地図情報", "url": "https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/findAddressCandidates", "sou